"""Streamlit review queue for the option-level reports generated by U3."""

import argparse
import re
from html import escape
from pathlib import Path
from sqlite3 import Error as SQLiteError
from urllib.parse import urlsplit

import streamlit as st

from trongpok.decisions import save_decision
from trongpok.reviewer_data import (
    DECISION_READ_ERROR,
    load_listings,
    load_queue,
    resolve_thumbnail,
)
from trongpok.reviewer_table import option_table


ROOT = Path(__file__).resolve().parents[2]
SAMPLE = ROOT / "tests/fixtures/u4"
PRIORITIES = {
    "RED": ("Red", "Review first", "🔴"),
    "YELLOW": ("Yellow", "Check by hand", "🟡"),
    "GREY": ("Grey", "Not enough data", "⚪"),
    "GREEN": ("Green", "No flags found (not a guarantee)", "🟢"),
}
CHECKS = {
    "Q1": "Price far below the market",
    "Q2": "Capacity missing from the brand page",
    "Q3": "Measured shortfalls from multiple buyers",
    "Q4": "Evidence needs a closer look",
    "Q5": "Matched buyer reviews",
    "grey": "Evidence coverage",
}
VERDICTS = {"unsure": "Unsure", "mismatch": "Mismatch", "no_mismatch": "No mismatch"}


def arguments():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--flags-dir", type=Path, default=ROOT / "out/flags")
    parser.add_argument("--listings-dir", type=Path, default=ROOT / "data/listings")
    parser.add_argument("--decisions-db", type=Path, default=ROOT / "out/decisions.sqlite3")
    parser.add_argument("--demo", action="store_true", help="Open the labelled sample queue first")
    return parser.parse_args()


def priority_label(colour):
    _, label, dot = PRIORITIES[colour]
    return f"{dot} {label}"


def display_text(value):
    """Keep captured text literal in Markdown and preserve the product wording rules."""
    return "".join(f"\\{c}" if c in r"\`*_{}[]<>#+-.!|$~" else c for c in public_text(value))


def public_text(value):
    return re.sub(r"\b(?:fake|fraud)\b", "[redacted]", str(value), flags=re.IGNORECASE)


def date_text(value):
    return str(value)[:10] if value else "Date unavailable"


def amount(value):
    if isinstance(value, (int, float)):
        return f"฿{value:,.2f}".removesuffix(".00")
    return "Unavailable"


def source_link(url, label):
    if not isinstance(url, str):
        return
    try:
        parsed = urlsplit(url)
    except ValueError:
        return
    if parsed.scheme not in {"http", "https"} or not parsed.hostname or parsed.username is not None:
        return
    if parsed.hostname.endswith(".invalid"):
        st.caption(f"{label} · {parsed.hostname}{parsed.path} · Sample")
    else:
        st.link_button(label, url)


def quote_block(text, buyer=None, date=None, measurement=None):
    if not text:
        return
    # Only display the field reserved for masked public labels, with masking present.
    buyer = buyer if isinstance(buyer, str) and any(c in buyer for c in "*•…") else "Buyer"
    metadata = " · ".join(part for part in (buyer, date_text(date), measurement) if part)
    # Use literal text for quotes, including embedded Markdown and Thai review text.
    st.html(
        '<blockquote style="margin:0; padding:.45rem .75rem; border-left:3px solid #898483;'
        ' background:color-mix(in srgb, currentColor 4%, transparent); border-radius:0 .5rem .5rem 0">'
        f'<div style="white-space:pre-wrap">{escape(public_text(text))}</div>'
        f'<small>{escape(public_text(metadata))}</small></blockquote>'
    )


def listing_context(listing, option, *, sample):
    if option:
        st.caption(
            f"Was {amount(option.get('was_thb'))}  ·  Now {amount(option.get('now_thb'))}"
            f"  ·  Captured {date_text(listing.get('captured_at'))}"
        )
    if sample and listing.get("spec_text"):
        st.caption(display_text(listing["spec_text"]))
    if listing.get("url"):
        source_link(listing["url"], "Captured listing source")


def market_details(item):
    st.markdown("**Price compared with the market**")
    was, now, market = st.columns(3)
    was.caption("Was")
    was.write(amount(item.get("was_thb")))
    now.caption("Now")
    now.write(amount(item.get("now_thb")))
    market.caption("Normal market range")
    market.write(f"{amount(item.get('low_thb'))} – {amount(item.get('high_thb'))}")
    st.caption(f"Market range captured {date_text(item.get('date'))}")
    for source in item.get("sources", []):
        source_link(
            source.get("url"),
            f"Official offer · {amount(source.get('now_thb'))} · {date_text(source.get('date'))}",
        )


def capacity_details(item):
    official = item["source"] == "brand_page"
    st.markdown("**Brand capacity list**" if official else "**Capacities seen in official Mall offers**")
    capacities = ", ".join(f"{capacity} GB" for capacity in item.get("capacities_gb", []))
    if item.get("promise_gb") is not None:
        st.write(f"Advertised option · {item['promise_gb']:g} GB")
    st.write(f"Captured capacities · {capacities or 'Unavailable'}")
    if official:
        st.caption(f"Brand page captured {date_text(item.get('date'))}")
        source_link(item.get("url"), "Open brand page")
    else:
        for source in item.get("sources", []):
            source_link(source.get("url"), f"Official offer · {date_text(source.get('date'))}")


def review_details(item, listings_dir):
    quantity, unit = item.get("quantity"), item.get("unit")
    measurement = (
        f"{quantity:g} {unit}"
        if isinstance(quantity, (int, float)) and unit in {"MB", "GB", "TB", "GiB", "TiB"}
        else None
    )
    quote_block(item.get("quote"), item.get("buyer_masked"), item.get("date"), measurement)
    if not item.get("quote"):
        st.caption(f"Review captured {date_text(item.get('date'))} · Quote unavailable")
    if item.get("image_ref"):
        image = resolve_thumbnail(item["image_ref"], listings_dir, ROOT)
        if image is not None:
            st.image(str(image), caption="Captured buyer evidence", width=200)
        else:
            st.caption("Captured buyer image is unavailable in this checkout.")


def render_evidence(flag, listing, option, listings_dir, sample):
    reasons = flag["reasons"]
    st.markdown(f"**{display_text(reasons[0]) if reasons else 'Reason unavailable'}**")
    if len(reasons) > 1:
        st.caption("Other reasons for this option")
        for reason in reasons[1:]:
            st.markdown(f"- {display_text(reason)}")

    if not any(item.get("source") == "market_range" for item in flag["evidence"]):
        listing_context(listing, option, sample=sample)
    for item in flag["evidence"]:
        match item.get("source"):
            case "market_range":
                market_details(item)
            case "brand_page" | "mall_capacities":
                capacity_details(item)
            case "review":
                review_details(item, listings_dir)
            case "review_count":
                matched = item.get("matched_text_reviews")
                checked = item.get("checked_text_reviews")
                if matched is not None and checked is not None:
                    st.caption(f"{checked} of {matched} matched text reviews checked")
            case "option":
                st.caption(f"Captured capacity · {display_text(item.get('capacity_text') or 'Unavailable')}")

    if sample and flag["colour"] == "GREEN":
        variation = option.get("variation_label")
        if variation and sum(item["variation_label"] == variation for item in listing["options"]) == 1:
            matched = {
                review["review_id"]: review for review in listing["reviews"]
                if review.get("variation_label") == variation and review["text"].strip()
            }
            if matched:
                with st.expander("Matched sample review excerpts"):
                    for review in list(matched.values())[:3]:
                        quote_block(review["text"], review["buyer_masked"], review["date"])

    if flag["colour"] == "GREY" and flag["confidence"]["missing_evidence"]:
        st.markdown("**Evidence still needed**")
        for item in flag["confidence"]["missing_evidence"]:
            st.markdown(f"- {display_text(item)}")
    with st.expander("Decision path"):
        st.caption("Order of checks and which one set the review priority.")
        for entry in flag["path"]:
            check, _, status = entry.partition(": ")
            if check in CHECKS:
                status_label = {
                    "decided": "Set priority",
                    "triggered": "Also triggered",
                    "clear": "No reason recorded",
                }.get(status, "Unavailable")
                st.write(f"{CHECKS[check]} · {status_label}")


def render_confidence(confidence):
    st.markdown("**How confidence was calculated**")
    st.caption("This score describes the evidence behind the priority. The reviewer decides the verdict.")
    st.write("Starting score · **50 points**")
    if confidence["adjustments"]:
        for adjustment in confidence["adjustments"]:
            st.markdown(f"- **{adjustment['points']:+d} points** · {display_text(adjustment['reason'])}")
    else:
        st.caption("No evidence adjustments recorded.")
    rounds = confidence["rounds"]
    st.caption(
        f"Base after standard checks · {confidence['base']}% · Additional confidence rounds · {rounds}"
    )
    st.markdown("**What could change this score**")
    if confidence["missing_evidence"]:
        for item in confidence["missing_evidence"]:
            st.markdown(f"- {display_text(item)}")
    else:
        st.caption("The report lists no missing evidence.")


def render_decision(flag, db, can_save):
    st.caption(f"Verdict · {VERDICTS[flag['verdict']]}")
    decision = flag["reviewer_decision"]
    if decision:
        saved = "Accepted" if decision["decision"] == "accepted" else "Dismissed"
        st.write(f"{saved} · {date_text(decision['at'])}")
        st.text(public_text(decision["reason"]))
        return
    if not can_save:
        st.error("Decisions are temporarily unavailable. Close this case and refresh the queue.")
        return
    with st.form("review-decision"):
        action = st.radio("Action", ["Accept", "Dismiss"], horizontal=True, index=None)
        st.caption("Accept records “Mismatch”. Dismiss records “No mismatch”.")
        note = st.text_area("Reviewer note (required)", placeholder="Record the evidence behind your decision.")
        saved = st.form_submit_button("Save decision", type="primary")
    if saved:
        if not action or not note.strip():
            st.error("Choose Accept or Dismiss and enter a reviewer note.")
            return
        try:
            save_decision(
                db, flag["listing_id"], flag["option_id"],
                "accepted" if action == "Accept" else "dismissed",
                note.strip(),
            )
        except (OSError, SQLiteError):
            st.error("The decision could not be saved. Your note is still here. Try again.")
            return
        st.session_state.decision_saved = True
        st.rerun()


@st.dialog("Review option", width="medium", on_dismiss="rerun")
def review_dialog(flag, listing, option, listings_dir, db, sample, can_save):
    st.subheader(display_text(listing.get("title") or "Storage listing"))
    st.caption(
        f"{display_text(option.get('variation_label') or flag['option_id'])} · "
        f"{priority_label(flag['colour'])} · {flag['confidence']['score']}% confidence"
        + (" · Sample" if sample else "")
    )
    evidence, confidence, decision = st.tabs(["Evidence", "Confidence details", "Reviewer decision"])
    with evidence:
        render_evidence(flag, listing, option, listings_dir, sample)
    with confidence:
        render_confidence(flag["confidence"])
    with decision:
        render_decision(flag, db, can_save)


def render_queue(flags, listings, sample):
    rows = []
    options = {}
    for flag in flags:
        listing = listings.get(flag["listing_id"], {})
        option = next((item for item in listing.get("options", [])
                       if item.get("option_id") == flag["option_id"]), {})
        title = listing.get("title") or f"Listing {flag['listing_id']}"
        key = (flag["listing_id"], flag["option_id"])
        rows.append({
            "key": list(key),
            "listing": public_text(title),
            "variant": public_text(option.get("variation_label") or flag["option_id"]),
            "colour": flag["colour"].lower(),
            "priority": PRIORITIES[flag["colour"]][1],
            "confidence": flag["confidence"]["score"],
            "verdict": VERDICTS[flag["verdict"]],
        })
        options[key] = (flag, listing, option)

    st.caption(f"{len(rows)} option{'s' if len(rows) != 1 else ''} · Select a row to review its evidence."
               + (" · Sample data" if sample else ""))
    selection = option_table(data=rows, key="review-table", on_opened_change=lambda: None).opened
    return options.get(tuple(selection)) if selection else None


def main():
    args = arguments()
    st.set_page_config(page_title="ตรงปก Queue", page_icon="📋", layout="wide")
    st.html(
        "<style>.stMainBlockContainer{max-width:76rem;padding-top:3.75rem}"
        '[data-testid="stAppDeployButton"]{display:none}'
        "div[data-testid=stDialog] section{max-height:86vh}</style>"
    )
    st.caption("ตรงปก Queue")
    st.title("Review queue")
    st.write("Review storage listings one option at a time. Open a row to check its evidence before deciding.")

    source, refresh = st.columns([5, 1], vertical_alignment="bottom")
    has_reports = any(args.flags_dir.glob("*.json"))
    with source:
        data_source = st.segmented_control(
            "Queue source", ["Captured data", "Sample data"],
            default="Sample data" if args.demo or not has_reports else "Captured data",
            label_visibility="collapsed",
        )
    with refresh:
        st.button("Refresh queue")
    sample = data_source == "Sample data" or (data_source is None and (args.demo or not has_reports))
    flags_dir = SAMPLE / "flags" if sample else args.flags_dir
    listings_dir = SAMPLE / "listings" if sample else args.listings_dir
    db = args.decisions_db.with_name("sample-" + args.decisions_db.name) if sample else args.decisions_db

    if sample:
        st.info("Sample data for the demo. Decisions in this view are saved separately.")
    with st.spinner("Loading review options…", show_time=False):
        flags, report_issues = load_queue(flags_dir, db)
        listings, capture_issues = load_listings(listings_dir)
    for issue in report_issues + capture_issues:
        st.warning(issue)
    if st.session_state.pop("decision_saved", False):
        st.success("Reviewer decision saved.")
    if not flags:
        st.info(
            "No review options are available. Refresh the queue after reports are added."
            if report_issues else
            "No flag reports yet. Choose Sample data to try the queue."
        )
        return

    filters, verdicts = st.columns(2)
    with filters:
        labels = {label: colour for colour, (label, _, _) in PRIORITIES.items()}
        priority = st.selectbox("Priority", ["All priorities", *labels])
    with verdicts:
        verdict = st.selectbox("Verdict", ["All verdicts", *VERDICTS.values()])
    filtered = [
        flag for flag in flags
        if (priority == "All priorities" or flag["colour"] == labels[priority])
        and (verdict == "All verdicts" or VERDICTS[flag["verdict"]] == verdict)
    ]
    if not filtered:
        st.info("No options match these filters.")
        return

    selected = render_queue(filtered, listings, sample)
    if selected:
        review_dialog(*selected, listings_dir, db, sample, DECISION_READ_ERROR not in report_issues)


if __name__ == "__main__":
    main()
